 private const string Op="11111111111111111111111111111111";
 private static AdminCustomer Row(string tenant="T001",string id="client-one",bool active=true)=>new(tenant,id,"Aisha Khan","aisha@example.test","Household",active,1,true,true);
 private static InMemoryCustomerAdministration Repo()=>new([Row(),Row("T002"),Row("T002",id:"foreign-only"),Row(id:"client-two")]);
 private static CustomerStatusChange Change(long version=1,bool active=false,string operation=Op)=>new(operation,version,active,"Requested account suspension");
 [Fact]public async Task GoldenJourneyListsDetailsSuspendsReactivatesAndRetainsExactReceipts()
 {
  await using var host=await Host.Start();var c=host.Client;
  var page=await c.GetFromJsonAsync<AdminCustomerPage>("");Assert.Equal(2,page!.Total);Assert.Equal(2,page.Active);Assert.Equal("Aisha Khan",page.Items[0].DisplayName);
  var row=await c.GetFromJsonAsync<AdminCustomer>("client-one");Assert.True(row!.OwnerLinked);Assert.Equal("aisha@example.test",row.Email);
  var first=await c.PostAsJsonAsync("client-one/status",Change());Assert.Equal(HttpStatusCode.OK,first.StatusCode);var receipt=await first.Content.ReadFromJsonAsync<CustomerStatusReceipt>();Assert.False(receipt!.After.Active);Assert.Equal(2,receipt.After.Version);Assert.Equal("A900",receipt.RecordedBy);
  var second=await c.PostAsJsonAsync("client-one/status",Change(2,true,"22222222222222222222222222222222"));Assert.Equal(HttpStatusCode.OK,second.StatusCode);
  var replay=await c.PostAsJsonAsync("client-one/status",Change());Assert.Equal(receipt,await replay.Content.ReadFromJsonAsync<CustomerStatusReceipt>());
  var detail=await c.GetFromJsonAsync<AdminCustomer>("client-one");Assert.True(detail!.Active);Assert.Equal(3,detail.Version);
  var history=await c.GetFromJsonAsync<CustomerStatusHistory>("client-one/history");Assert.Equal([3L,2L],history!.Items.Select(x=>x.After.Version));Assert.Null(history.NextBeforeVersion);
  var exact=await c.GetFromJsonAsync<CustomerStatusReceipt>("client-one/changes/"+Op);Assert.Equal(receipt,exact);
  var json=await c.GetStringAsync("client-one");Assert.DoesNotContain("ownershipEvidence",json);Assert.DoesNotContain("pan",json);Assert.DoesNotContain("dateOfBirth",json);Assert.DoesNotContain("ownerActorId",json);Assert.Equal("no-store",first.Headers.CacheControl?.ToString());
 }
