 [Fact]public async Task RejectsOversizedAndWrongContentTypeWithoutMutation(){await using var h=await Host.Start();var json=JsonSerializer.Serialize(Change()with{Reason=new string('x',20000)},Json);Assert.Equal(HttpStatusCode.RequestEntityTooLarge,(await h.Client.PostAsync("client-one/status",new StringContent(json,Encoding.UTF8,"application/json"))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await h.Client.PostAsync("client-one/status",new StringContent(json))).StatusCode);Assert.True((await h.Repository.ReadAsync("T001","client-one",default))!.Active);}
 [Fact]public async Task ChangedPayloadCrossCustomerAndCrossAdministratorReuseRejects(){var r=Repo();await r.ChangeAsync("T001","A900","client-one",Change(),DateTimeOffset.UtcNow,default);foreach(var c in new[]{Change()with{Reason="Other reason"},Change()with{Active=true},Change()with{ExpectedVersion=2}})Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAsync("T001","A900","client-one",c,DateTimeOffset.UtcNow,default))).Status);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAsync("T001","A900","client-two",Change(),DateTimeOffset.UtcNow,default))).Status);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAsync("T001","A901","client-one",Change(),DateTimeOffset.UtcNow,default))).Status);}
 [Fact]public async Task SameOperationInAnotherTenantIsIndependentAndForeignReadsDoNotLeak(){var r=Repo();await r.ChangeAsync("T001","A900","client-one",Change(),DateTimeOffset.UtcNow,default);Assert.True((await r.ReadAsync("T002","client-one",default))!.Active);Assert.Null(await r.ReadAsync("T002","client-two",default));Assert.Null(await r.ReceiptAsync("T002","client-one",Op,default));await r.ChangeAsync("T002","A900","client-one",Change(),DateTimeOffset.UtcNow,default);Assert.Single((await r.HistoryAsync("T002","client-one",null,default)).Items);}
 [Fact]public async Task ConcurrentDifferentOperationsOnlyOneExpectedVersionWins(){var r=Repo();var results=await Task.WhenAll(new[]{Op,"22222222222222222222222222222222"}.Select(async op=>{try{await r.ChangeAsync("T001","A900","client-one",Change(operation:op),DateTimeOffset.UtcNow,default);return 200;}catch(TenantBoundaryException e){return e.Status;}}));Assert.Equal([200,409],results.Order());Assert.Single((await r.HistoryAsync("T001","client-one",null,default)).Items);}
 [Fact]public async Task ConcurrentIdenticalOperationsCommitOnce(){var r=Repo();var values=await Task.WhenAll(Enumerable.Range(0,6).Select(_=>r.ChangeAsync("T001","A900","client-one",Change(),DateTimeOffset.UtcNow,default)));Assert.All(values,x=>Assert.Equal(values[0],x));Assert.Single((await r.HistoryAsync("T001","client-one",null,default)).Items);}
 [Fact]public async Task ListAndHistoryPaginationAreBoundedCompleteAndImmutable(){var r=new InMemoryCustomerAdministration(Enumerable.Range(0,121).Select(i=>Row(id:$"client-{i:000}")));var list=await r.ListAsync("T001",new(),default);Assert.Equal(50,list.Items.Count);Assert.Equal(121,list.Total);var next=await r.ListAsync("T001",new(After:list.NextCursor),default);Assert.Equal("client-050",next.Items[0].CustomerId);var end=await r.ListAsync("T001",new(After:next.NextCursor),default);Assert.Equal(21,end.Items.Count);Assert.Null(end.NextCursor);CustomerStatusReceipt? first=null;for(var n=1;n<=111;n++){var receipt=await r.ChangeAsync("T001","A900","client-000",Change(n,n%2==0,Guid.NewGuid().ToString("N")),DateTimeOffset.UtcNow,default);first??=receipt;}var history=await r.HistoryAsync("T001","client-000",null,default);Assert.Equal(50,history.Items.Count);Assert.Equal(112,history.Items[0].After.Version);Assert.Equal(2,first!.After.Version);var past=await r.HistoryAsync("T001","client-000",history.NextBeforeVersion,default);Assert.Equal(62,past.Items[0].After.Version);Assert.Equal(first,await r.ReceiptAsync("T001","client-000",first.OperationId,default));}
 [Fact]public async Task SearchIsCaseInsensitiveLiteralAndStatusAware(){var r=Repo();Assert.Equal(2,(await r.ListAsync("T001",new("AISHA"),default)).Matching);Assert.Equal(0,(await r.ListAsync("T001",new("%"),default)).Matching);await r.ChangeAsync("T001","A900","client-one",Change(),DateTimeOffset.UtcNow,default);var page=await r.ListAsync("T001",new("","inactive"),default);Assert.Equal(1,page.Matching);Assert.False(Assert.Single(page.Items).Active);Assert.Equal(1,page.Active);}
 [Fact]public async Task NoOpStaleVersionAndSourceInactiveActivationReject(){var r=new InMemoryCustomerAdministration([Row(),Row(id:"locked",active:false)with{ActivationAvailable=false}]);foreach(var pair in new[]{("client-one",Change(active:true)),("client-one",Change(2)),("locked",Change(active:true))})Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAsync("T001","A900",pair.Item1,pair.Item2,DateTimeOffset.UtcNow,default))).Status);}
 [Theory][InlineData(401)][InlineData(403)]public async Task NonAdministratorCannotReadOrMutate(int status){await using var h=await Host.Start();h.Authority.Status=status;foreach(var path in new[]{"","client-one","client-one/history"})Assert.Equal((HttpStatusCode)status,(await h.Client.GetAsync(path)).StatusCode);Assert.Equal((HttpStatusCode)status,(await h.Client.PostAsJsonAsync("client-one/status",Change())).StatusCode);Assert.True((await h.Repository.ReadAsync("T001","client-one",default))!.Active);}
 [Fact]public async Task RevokedAuthorityBeforeCommitDoesNotWrite(){await using var h=await Host.Start();h.Authority.DenyAfter=1;Assert.Equal(HttpStatusCode.Forbidden,(await h.Client.PostAsJsonAsync("client-one/status",Change())).StatusCode);Assert.True((await h.Repository.ReadAsync("T001","client-one",default))!.Active);Assert.Empty((await h.Repository.HistoryAsync("T001","client-one",null,default)).Items);}
 [Fact]public async Task LostPostCommitAuthorityKeepsExactReplayAvailable(){await using var h=await Host.Start();h.Authority.DenyAfter=2;Assert.Equal(HttpStatusCode.Forbidden,(await h.Client.PostAsJsonAsync("client-one/status",Change())).StatusCode);Assert.False((await h.Repository.ReadAsync("T001","client-one",default))!.Active);h.Authority.DenyAfter=int.MaxValue;Assert.Equal(HttpStatusCode.OK,(await h.Client.PostAsJsonAsync("client-one/status",Change())).StatusCode);Assert.Single((await h.Repository.HistoryAsync("T001","client-one",null,default)).Items);}
