 private sealed class Authority:HttpMessageHandler
 {public int Status=200,Calls,DenyAfter=int.MaxValue,ChangeAfter=int.MaxValue;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;var status=Calls>DenyAfter?403:Status;var tenant=request.Headers.GetValues("X-Monergy-Tenant").Single();return Task.FromResult(new HttpResponseMessage((HttpStatusCode)status){Content=JsonContent.Create(status==200?(object)new TenantAdminContext(tenant,Calls>ChangeAfter?"A901":"A900",1,"TenantAdmin"):new{error="ADMINISTRATOR_REQUIRED"})});}}
 private sealed class Corrupt(ICustomerAdministrationRepository inner,string mode):ICustomerAdministrationRepository
 {public async Task<AdminCustomerPage> ListAsync(string t,AdminCustomerQuery q,CancellationToken c){var p=await inner.ListAsync(t,q,c);return mode=="list"?p with{Items=[p.Items[0]with{TenantId="foreign"}]}:p;}public Task<AdminCustomer?> ReadAsync(string t,string i,CancellationToken c)=>inner.ReadAsync(t,i,c);public async Task<CustomerStatusReceipt> ChangeAsync(string t,string a,string i,CustomerStatusChange x,DateTimeOffset n,CancellationToken c){var r=await inner.ChangeAsync(t,a,i,x,n,c);return mode=="mutation"?r with{After=r.After with{OwnerLinked=false}}:mode=="metadata"?r with{After=r.After with{DisplayName="Forged name"}}:r;}public async Task<CustomerStatusReceipt?> ReceiptAsync(string t,string i,string o,CancellationToken c){var r=await inner.ReceiptAsync(t,i,o,c);return mode=="readback"&&r is not null?r with{Reason="forged"}:r;}public Task<CustomerStatusHistory> HistoryAsync(string t,string i,long? b,CancellationToken c)=>inner.HistoryAsync(t,i,b,c);}
 private sealed class Host(WebApplication app,HttpClient client,InMemoryCustomerAdministration repository,Authority authority):IAsyncDisposable
 {public HttpClient Client=>client;public InMemoryCustomerAdministration Repository=>repository;public Authority Authority=>authority;public static async Task<Host> Start(string? corrupt=null){var builder=WebApplication.CreateBuilder(new WebApplicationOptions{EnvironmentName="Development"});builder.Logging.ClearProviders();builder.WebHost.UseUrls("http://127.0.0.1:0");var repository=Repo();var authority=new Authority();var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Monergy:ExecutionZone","CI_EPHEMERAL"}}).Build();builder.Services.AddSingleton(new TenantAccessClient(config,new HttpClient(authority)));builder.Services.AddSingleton<ICustomerAdministrationRepository>(corrupt is null?repository:new Corrupt(repository,corrupt));var app=builder.Build();app.MapCustomerAdministration();await app.StartAsync();var url=app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single();var client=new HttpClient{BaseAddress=new Uri(url+"/local/v1/administration/customers/")};client.DefaultRequestHeaders.Add("X-Monergy-Tenant","T001");client.DefaultRequestHeaders.Add("X-Monergy-Session","admin-session");return new(app,client,repository,authority);}public async ValueTask DisposeAsync(){client.Dispose();await app.DisposeAsync();}}
